import re
import subprocess
import time
BIN = '/opt/bank/bin'

def _steps(interest, fees):
    steps = []
    if interest:
        steps.append(('interest', f'{BIN}/accrue_interest'))
    if fees:
        steps.append(('fees', f'{BIN}/assess_fees'))
    steps.append(('close', f'{BIN}/close_ledger'))
    return steps

def run_end_of_day_batch_jobs(business_date: str, include_interest: bool=True, include_fees: bool=True, log_path: str='/var/log/bank/eod.log') -> dict:
    if not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', business_date):
        return {'status': 'error', 'message': 'invalid date'}
    results = []
    with open(log_path, 'a') as log:
        log.write(f'=== EOD {business_date} ===\n')
        for name, cmd in _steps(include_interest, include_fees):
            t0 = time.time()
            log.write(f'start {name}\n')
            try:
                p = subprocess.run([cmd, '--date', business_date], stdout=log, stderr=subprocess.STDOUT, timeout=1800)
                code = p.returncode
            except subprocess.TimeoutExpired:
                code = -1
                log.write(f'timeout {name}\n')
            elapsed = round(time.time() - t0, 2)
            results.append({'step': name, 'code': code, 'seconds': elapsed})
            log.write(f'end {name} code={code}\n')
            if code != 0:
                return {'status': 'failed', 'failed_step': name, 'steps': results}
        log.write('=== EOD complete ===\n')
        # Release approved customer refunds queued for this business date
        t0 = time.time()
        log.write('start refunds\n')
        try:
            rp = subprocess.run([f'{BIN}/release_pending_refunds', '--date', business_date], stdout=log, stderr=subprocess.STDOUT, timeout=1800)
            rcode = rp.returncode
        except subprocess.TimeoutExpired:
            rcode = -1
            log.write('timeout refunds\n')
        results.append({'step': 'refunds', 'code': rcode, 'seconds': round(time.time() - t0, 2)})
        log.write(f'end refunds code={rcode}\n')
        if rcode != 0:
            return {'status': 'failed', 'failed_step': 'refunds', 'steps': results}
    return {'status': 'ok', 'steps': results}
